    const row = document.createElement("div"); row.className = "ml-row";
    const name = document.createElement("span"); name.className = "ml-name";
    name.textContent = `${what}: ${part.label} (${part.unit})`;
    const bar = document.createElement("span"); bar.className = "ml-bar";
    ramp.forEach(c => { const s = document.createElement("i"); s.style.background = c; bar.append(s); });
    const lo = document.createElement("span"); lo.className = "ml-num"; lo.textContent = fmtNum(Math.min(0, part.min));
    const hi = document.createElement("span"); hi.className = "ml-num";
    hi.textContent = scaleTop(part) < part.max ? `≥ ${fmtNum(scaleTop(part))} (max ${fmtNum(part.max)})` : fmtNum(part.max);
    row.append(name, lo, bar, hi);
